import { DATA_ATTR } from "../constants";
import { logger } from "../utils/logger";
import { parseBlocks, type TemplateLookup } from "./template-parser";

/** Transforms one block element from version `from` to `from + 1`, in place on a detached copy. */
export interface TemplateMigration {
  templateId: string;
  from: number;
  migrate(element: Element): void;
}

export type MigrationIssueKind =
  "unknown-template" | "newer-version" | "invalid-version" | "missing-migration" | "migration-failed";

export interface MigrationIssue {
  kind: MigrationIssueKind;
  templateId: string;
  instanceId: string | null;
  from: number | null;
  message?: string;
}

export interface MigrationResult {
  html: string;
  changed: boolean;
  issues: MigrationIssue[];
}

/**
 * Explicit, targeted migrations of Loreframe blocks (spec §46). A block is replaced only after its whole
 * chain succeeded on a copy; otherwise the original markup stays exactly as it was (spec §47).
 */
export class MigrationService {
  readonly #templates: TemplateLookup;
  readonly #migrations = new Map<string, TemplateMigration>();

  constructor(templates: TemplateLookup) {
    this.#templates = templates;
  }

  register(migration: TemplateMigration): void {
    if (!Number.isInteger(migration.from) || migration.from < 1) {
      throw new Error(`Migration for "${migration.templateId}" needs a positive integer "from"`);
    }
    const key = migrationKey(migration.templateId, migration.from);
    if (this.#migrations.has(key)) throw new Error(`Migration ${key} is already registered`);
    this.#migrations.set(key, migration);
  }

  migrateHtml(html: string): MigrationResult {
    const container = document.createElement("template");
    container.innerHTML = html;
    const issues: MigrationIssue[] = [];
    let changed = false;

    // Innermost blocks first, so an outer block's copy already contains its migrated children.
    for (const block of parseBlocks(container.content, this.#templates).reverse()) {
      const base = { templateId: block.templateId, instanceId: block.instanceId, from: block.version };
      if (block.status === "unknown") issues.push({ kind: "unknown-template", ...base });
      else if (block.status === "newer") issues.push({ kind: "newer-version", ...base });
      else if (block.status === "invalid") issues.push({ kind: "invalid-version", ...base });
      if (block.status !== "outdated" || block.version === null) continue;

      const target = this.#templates.get(block.templateId)?.version ?? block.version;
      const outcome = this.#migrateBlock(block.element, block.version, target);
      if (outcome.issue) {
        issues.push({ ...base, ...outcome.issue });
        continue;
      }
      block.element.replaceWith(outcome.element);
      changed = true;
    }

    // Unchanged content is returned verbatim so callers can skip document updates.
    return { html: changed ? container.innerHTML : html, changed, issues: issues.reverse() };
  }

  #migrateBlock(
    original: Element,
    from: number,
    to: number,
  ): { element: Element; issue?: undefined } | { issue: Pick<MigrationIssue, "kind" | "from" | "message"> } {
    const templateId = original.getAttribute(DATA_ATTR.template) ?? "";
    const steps: TemplateMigration[] = [];
    for (let version = from; version < to; version++) {
      const step = this.#migrations.get(migrationKey(templateId, version));
      if (!step) return { issue: { kind: "missing-migration", from: version } };
      steps.push(step);
    }

    const copy = original.cloneNode(true) as Element;
    let version = from;
    try {
      for (const step of steps) {
        step.migrate(copy);
        version++;
        copy.setAttribute(DATA_ATTR.version, String(version));
      }
    } catch (error) {
      logger.error(`Migration ${migrationKey(templateId, version)} failed; original block kept`, error);
      return { issue: { kind: "migration-failed", from: version, message: String(error) } };
    }
    return { element: copy };
  }
}

function migrationKey(templateId: string, from: number): string {
  return `${templateId}@${from}`;
}
